    78  void event_init(void)
    79  {
    80          my_event_is_running = false;
    81
    82          // security
    83          pthread_mutex_init(&my_mutex, (const pthread_mutexattr_t *)NULL);
    84          init();
    85
    86          assert(-1 != pthread_cond_init(&my_cond_start_is_required, NULL));
    87          assert(-1 != pthread_cond_init(&my_cond_stop_is_required, NULL));
    88          assert(-1 != pthread_cond_init(&my_cond_stop_is_acknowledged, NULL));
    89
    90          pthread_attr_t a_attrib;
    91
    92          if (pthread_attr_init(&a_attrib) == 0
    93              && pthread_attr_setdetachstate(&a_attrib, PTHREAD_CREATE_JOINABLE) == 0) {
    94                  thread_inited = (0 == pthread_create(&my_thread,
    95                                                       &a_attrib,
    96                                                       polling_thread,
    97                                                       (void *)NULL));
    98          }
    99          assert(thread_inited);
   100          pthread_attr_destroy(&a_attrib);
   101  }
