   103  static espeak_EVENT *event_copy(espeak_EVENT *event)
   104  {
   105          if (event == NULL)
   106                  return NULL;
   107
   108          espeak_EVENT *a_event = (espeak_EVENT *)malloc(sizeof(espeak_EVENT));
   109          if (a_event) {
   110                  memcpy(a_event, event, sizeof(espeak_EVENT));
   111
   112                  switch (event->type)
   113                  {
   114                  case espeakEVENT_MARK:
   115                  case espeakEVENT_PLAY:
   116                          if (event->id.name)
   117                                  a_event->id.name = strdup(event->id.name);
   118                          break;
   119
   120                  default:
   121                          break;
   122                  }
   123          }
   124
   125          return a_event;
   126  }
