   128  // Call the user supplied callback
   129  //
   130  // Note: the current sequence is:
   131  //
   132  // * First call with: event->type = espeakEVENT_SENTENCE
   133  // * 0, 1 or several calls: event->type = espeakEVENT_WORD
   134  // * Last call: event->type = espeakEVENT_MSG_TERMINATED
   135  //
   136
   137  static void event_notify(espeak_EVENT *event)
   138  {
   139          static unsigned int a_old_uid = 0;
   140
   141          espeak_EVENT events[2];
   142          memcpy(&events[0], event, sizeof(espeak_EVENT));     // the event parameter in the callback function should be an array of eventd
   143          memcpy(&events[1], event, sizeof(espeak_EVENT));
   144          events[1].type = espeakEVENT_LIST_TERMINATED;           // ... terminated by an event type=0
   145
   146          if (event && my_callback) {
   147                  switch (event->type)
   148                  {
   149                  case espeakEVENT_SENTENCE:
   150                          my_callback(NULL, 0, events);
   151                          a_old_uid = event->unique_identifier;
   152                          break;
   153                  case espeakEVENT_MSG_TERMINATED:
   154                  case espeakEVENT_MARK:
   155                  case espeakEVENT_WORD:
   156                  case espeakEVENT_END:
   157                  case espeakEVENT_PHONEME:
   158                  {
   159                          if (a_old_uid != event->unique_identifier) {
   160                                  espeak_EVENT_TYPE a_new_type = events[0].type;
   161                                  events[0].type = espeakEVENT_SENTENCE;
   162                                  my_callback(NULL, 0, events);
   163                                  events[0].type = a_new_type;
   164                                  usleep(50000);
   165                          }
   166                          my_callback(NULL, 0, events);
   167                          a_old_uid = event->unique_identifier;
   168                  }
   169                          break;
   170                  case espeakEVENT_LIST_TERMINATED:
   171                  case espeakEVENT_PLAY:
   172                  default:
   173                          break;
   174                  }
   175          }
   176  }
