   178  static int event_delete(espeak_EVENT *event)
   179  {
   180          if (event == NULL)
   181                  return 0;
   182
   183          switch (event->type)
   184          {
   185          case espeakEVENT_MSG_TERMINATED:
   186                  event_notify(event);
   187                  break;
   188          case espeakEVENT_MARK:
   189          case espeakEVENT_PLAY:
   190                  if (event->id.name)
   191                          free((void *)(event->id.name));
   192                  break;
   193          default:
   194                  break;
   195          }
   196
   197          free(event);
   198          return 1;
   199  }
