   201  espeak_ng_STATUS event_declare(espeak_EVENT *event)
   202  {
   203          if (!event)
   204                  return EINVAL;
   205
   206          espeak_ng_STATUS status;
   207          if ((status = pthread_mutex_lock(&my_mutex)) != ENS_OK) {
   208                  my_start_is_required = true;
   209                  return status;
   210          }
   211
   212          espeak_EVENT *a_event = event_copy(event);
   213          if ((status = push(a_event)) != ENS_OK) {
   214                  event_delete(a_event);
   215                  pthread_mutex_unlock(&my_mutex);
   216          } else {
   217                  my_start_is_required = true;
   218                  pthread_cond_signal(&my_cond_start_is_required);
   219                  status = pthread_mutex_unlock(&my_mutex);
   220          }
